function toNumbers(values) { return values.map(v => Number(v)).filter(v => !Number.isNaN(v) && Number.isFinite(v)); }
function filterByCondition(values, condition) {
    const match = String(condition || "").trim().match(/^value\s*(>=|<=|>|<|==|=|!=)\s*(-?\d+(\.\d+)?)$/);
